<template><section class="panel" style="margin-bottom:20px"><div class="panel-heading"><h2>本地工作助手</h2><el-button @click="load" :loading="busy">刷新助手状态</el-button></div><el-descriptions v-if="state" :column="1" border><el-descriptions-item label="基础模型文件">{{state.base_ready?'已就绪':'缺失'}}</el-descriptions-item><el-descriptions-item label="LoRA 适配器">{{state.adapter_ready?'已就绪':'缺失'}}</el-descriptions-item><el-descriptions-item label="内存加载">{{state.loaded?'已加载':(state.phase==='loading'?'正在后台预热':state.error||'尚未加载')}}</el-descriptions-item><el-descriptions-item label="路由验证">{{state.metrics?.accuracy == null?'未测量':`${(state.metrics.accuracy*100).toFixed(0)}% · ${state.metrics.test_samples} 条验证指令`}}</el-descriptions-item></el-descriptions><p class="muted">助手状态独立于两份心电分类模型。加载失败时请检查本机模型文件并重启服务；刷新状态只重新查询，不会重新下载模型。工具选择存在误差，每轮需核对并确认；历史训练结果保持原始记录。</p></section></template>
<script setup lang="ts">import{ref,onMounted}from'vue';import{get}from'../api';const state=ref<any>(null),busy=ref(false);async function load(){busy.value=true;try{state.value=await get('/agent/status');}finally{busy.value=false;}}onMounted(load);</script>
